// Simulating memory pressure monitoring and cache eviction
class MobileMemoryManager {
  constructor(maxHeapMB) {
    this.maxHeapMB = maxHeapMB;
    this.cache = new Map();
  }

  allocate(key, sizeMB) {
    const currentUsage = this.getCurrentUsage();
    if (currentUsage + sizeMB > this.maxHeapMB) {
      console.log(`[Low Memory] Threshold reached! Invoking Garbage Collection / Eviction...`);
      this.evictOldestCache();
    }
    this.cache.set(key, { size: sizeMB, data: `Heavy AI Asset ${key}` });
    console.log(`Allocated ${sizeMB}MB for '${key}'. Current heap usage: ${this.getCurrentUsage()}MB`);
  }

  getCurrentUsage() {
    let total = 0;
    for (let item of this.cache.values()) total += item.size;
    return total;
  }

  evictOldestCache() {
    const firstKey = this.cache.keys().next().value;
    if (firstKey) {
      this.cache.delete(firstKey);
      console.log(`[LMK/GC] Evicted cache key: '${firstKey}' to free memory.`);
    }
  }
}

const manager = new MobileMemoryManager(100);
manager.allocate('ModelA', 40);
manager.allocate('ModelB', 50);
