const jwt = require('jsonwebtoken');

// Secret key for signing tokens (stored securely on backend)
const SECRET_KEY = 'gurugram_university_ai_lab';

function generateToken(user) {
  // Payload containing user info and AI access role
  const payload = { id: user.id, role: user.role };
  // Sign token to expire in 1 hour
  return jwt.sign(payload, SECRET_KEY, { expiresIn: '1h' });
}

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Token missing' });

  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid or expired token' });
    req.user = user;
    // Proceed to AI model inference endpoint
  });
}

